// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper actors
    address fromAddress = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    // General rule tested: when called by the configured from address and _tos.length>0,
    // the reference contract's transfer(...) always returns true (does not revert and returns true).
    // The mutant inverts the success check and can cause a different return behavior when an
    // external callee either reverts or succeeds — to exercise that difference we deploy helpers
    // that either revert or succeed on calldata and pass their addresses as recipients.
    function testFuzz_property(uint8 callBehavior, uint8 tosLen) public {
        // Keep tosLen in a reasonable but wide range: 1..4 (must be >0 to satisfy require)
        tosLen = uint8(bound(tosLen, 1, 4));
        // callBehavior: 0 => callee reverts, 1 => callee returns success
        callBehavior = uint8(bound(callBehavior, 0, 1));

        // Deploy helper that either reverts or succeeds when called
        address helper;
        if (callBehavior == 0) {
            helper = address(new Reverter());
        } else {
            helper = address(new Succeeder());
        }

        // Build arrays for _tos and v. Use helper as each _tos entry so the low-level call is to our helper.
        address[] memory tos = new address[](tosLen);
        uint256[] memory v = new uint256[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            tos[i] = helper;
            v[i] = 1; // minimal positive amount
        }

        // Call transfer as the required sender
        bool ok;
        vm.prank(fromAddress);
        try c.transfer(tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // Single assertion: for the correct reference contract, when caller is the configured from
        // and _tos.length>0, transfer must return true (so ok==true) for ALL inputs (both helper types).
        // The mutant that inverted the success check will allow ok==false for some inputs (e.g., when
        // the callee returns success, mutant reverts so ok false or inverted), so this test will fail
        // on the mutant for some fuzzed inputs.
        assertTrue(ok);
    }
}

// Helper that always reverts on call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

// Helper that always succeeds (does nothing)
contract Succeeder {
    fallback() external payable {
        // succeed silently
    }
}
